graphQueries.baseQuery:
{{graphQueriesTableName}}
| where SourceSystem == "PolySwarm" and LastUpdateMethod == "PolySwarm hunting"
| summarize count() by bin(TimeGenerated, 1h)

sampleQueries.query:
{{graphQueriesTableName}}
| where SourceSystem == "PolySwarm" and LastUpdateMethod == "PolySwarm hunting"
| sort by TimeGenerated desc

{{graphQueriesTableName}}
| where SourceSystem == "PolySwarm" and LastUpdateMethod == "PolySwarm hunting" and Confidence >= 90
| sort by TimeGenerated desc
